(function(){
function shuffled(items,random=Math.random){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function recentTypeOrder(history=[]){const seen=new Set(),out=[];for(const x of history){if(!seen.has(x.templateId)){seen.add(x.templateId);out.push(x.templateId)}}return out}
function chooseVariant(template,history,usedKeys,random=Math.random){const recent=new Set(history.slice(0,80).map(x=>x.key)),indices=shuffled(template.variants.map((_,i)=>i),random);return indices.sort((a,b)=>Number(recent.has(template.id+':'+a))-Number(recent.has(template.id+':'+b))).find(i=>!usedKeys.has(template.id+':'+i))??indices[0]??0}
function chooseTemplate(pool,usedTypes,topicCounts,recentTypes,preferredTopics,random=Math.random){const recentIndex=new Map(recentTypes.map((id,i)=>[id,i])),ranked=pool.map(t=>{const repeated=usedTypes.has(t.id)?10000:0,recent=recentIndex.has(t.id)?Math.max(0,120-recentIndex.get(t.id)*4):0,topic=(topicCounts[t.topic]||0)*35,focus=preferredTopics?.size&&!preferredTopics.has(t.topic)?45:0;return{t,score:repeated+recent+topic+focus+random()*12}}).sort((a,b)=>a.score-b.score);return ranked[0]?.t}
function buildPlan({config,level,mode='normal',history=[],weakTopics=[],count=10,random=Math.random}){const levelPool=config.templates.filter(t=>t.level===level),pool=mode==='weak'?config.templates:levelPool;if(!pool.length)return[];const usedTypes=new Set(),usedKeys=new Set(),topicCounts={},recentTypes=recentTypeOrder(history),preferred=new Set(weakTopics.slice(0,4)),items=[];for(let i=0;i<count;i++){let candidates=pool;if(mode==='weak'){const wantWeak=i<Math.ceil(count*.7);const focused=pool.filter(t=>wantWeak?preferred.has(t.topic):!preferred.has(t.topic));if(focused.length)candidates=focused}let template=chooseTemplate(candidates,usedTypes,topicCounts,recentTypes,preferred,random);if(!template)template=pool[i%pool.length];if(usedTypes.size>=pool.length)usedTypes.clear();const variantIndex=chooseVariant(template,history,usedKeys,random),key=template.id+':'+variantIndex;items.push({templateId:template.id,variantIndex,key});usedTypes.add(template.id);usedKeys.add(key);topicCounts[template.topic]=(topicCounts[template.topic]||0)+1}return items}
function alternate({config,current,items=[],history=[],random=Math.random}){const original=config.templates.find(t=>t.id===current.templateId);if(!original)return current;const used=new Set(items.map(x=>x.templateId)),same=config.templates.filter(t=>t.topic===original.topic&&t.level===original.level&&t.id!==original.id),fallback=config.templates.filter(t=>t.level===original.level&&t.id!==original.id),recent=recentTypeOrder(history);let pool=same.filter(t=>!used.has(t.id));if(!pool.length)pool=fallback.filter(t=>!used.has(t.id));if(!pool.length)pool=same.length?same:fallback;if(pool.length){const chosen=chooseTemplate(pool,new Set(),{},recent,null,random),variantIndex=chooseVariant(chosen,history,new Set(items.map(x=>x.key)),random);return{templateId:chosen.id,variantIndex,key:chosen.id+':'+variantIndex}}const variantIndex=chooseVariant(original,history,new Set(items.map(x=>x.key)),random);return{templateId:original.id,variantIndex,key:original.id+':'+variantIndex}}
window.MatematikONPracticePlanner={buildPlan,alternate,chooseVariant,recentTypeOrder};
})();
